// REPLACE with your real source (an OPC UA / Modbus / MQTT / HTTP node). It must return ONE item whose json is
// { <wertek variable key>: <number> }. Here it SIMULATES a boiler-feed pump.
const t = Date.now() / 1000, r1 = (x) => Math.round(x * 10) / 10;
return [{ json: {
  flow_m3h: r1(412.5 + 5 * Math.sin(t / 30)), head_m: r1(85.2 + 0.5 * Math.sin(t / 45)),
  kw: r1(118.4 + 2 * Math.sin(t / 30)), seal_temp_c: r1(62.3 + 0.4 * Math.sin(t / 60)),
  vibration_mm_s: r1(2.8 + 0.2 * Math.sin(t / 20)) } }];

// Build one IAES 2.0 asset.measurement per number. The asset id and the position come from the "config" node;
// the API KEY is NOT here: the HTTP Request node takes it from an n8n credential (Header Auth).
const cfg = $('config').first().json;
const UNITS = { flow_m3h: "m³/h", head_m: "m", kw: "kW", pf: "1", vibration_mm_s: "mm/s",
                bearing_temp_c: "°C", winding_temp_c: "°C", seal_temp_c: "°C" };
const uuid = () => "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
  const r = Math.random() * 16 | 0; return (c === "x" ? r : (r & 3 | 8)).toString(16); });
const when = new Date().toISOString().replace(/\.\d{3}Z$/, "Z"), corr = uuid(), events = [], skipped = [];
for (const [k, v] of Object.entries($input.first().json)) {
  if (!(k in UNITS) || typeof v !== "number" || !isFinite(v)) { skipped.push(k); continue; }   // never invent a value
  events.push({ spec_version: "2.0", event_id: uuid(), correlation_id: corr, event_type: "asset.measurement",
    timestamp: when, source: "wertek_integrations.n8n", dataschema: "https://iaes.dev/schema/v2/asset.measurement",
    asset: { asset_id: cfg.asset_id }, data: { measurement_type: k, value: v, unit: UNITS[k], location: cfg.position } });
}
return [{ json: { events, skipped } }];

// One answer per event. A batch where NOTHING was accepted answers HTTP 422 and still carries them:
// it is an answer, not a failure. 504 = faster than the contracted cadence (dropped, retry later).
const sent = $('build events').first().json, res = $input.first().json.body || {};
const by = {}; (res.results || []).forEach((x) => { by[x.event_id] = x; });
const answers = sent.events.map((e) => ({ key: e.data.measurement_type, value: e.data.value, c: (by[e.event_id] || {}).c }));
// When Wertek refuses the CALL itself (401 = the key was not accepted or not sent), there are no per-event answers:
// say why, with the server's own words (they never contain the key).
const why = (res.results ? null : (res.error || res.detail || res.message || "no per-event results in the answer"));
return [{ json: { http: $input.first().json.statusCode, answers, skipped: sent.skipped,
                  ok: answers.every((a) => [100, 101, 102, 504].includes(a.c)), why } }];
